#!/usr/bin/env python3
"""Five distinct static, client-side tools for 2026-10-21."""
import json, pathlib
R=pathlib.Path(__file__).resolve().parents[1]
STYLE='''
:root{--ink:#173747;--muted:#5d7681;--teal:#08776d;--line:#dbe9e8;--bg:#f3f9f8}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px/1.55 system-ui,-apple-system,'Segoe UI',sans-serif;color:var(--ink)}.app{max-width:1130px;margin:auto;padding:34px 18px 60px}.tag{font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:1.5px;color:var(--teal)}h1{font-size:clamp(31px,4vw,45px);line-height:1.12;letter-spacing:-1px;margin:10px 0}h2{font-size:20px;margin:0 0 15px}.intro{font-size:17px;max-width:780px;color:var(--muted)}.grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(300px,.9fr);gap:20px;margin-top:24px;align-items:start}.box{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:0 8px 30px #0d55400a}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.fields.three{grid-template-columns:repeat(3,minmax(0,1fr))}label{display:flex;flex-direction:column;gap:5px;color:#41606c;font-size:13px;font-weight:750}input,select,textarea{width:100%;min-width:0;border:1px solid #b9cfcd;border-radius:9px;padding:11px;font:inherit;color:#183847;background:#fff}textarea{min-height:80px;resize:vertical}input:focus,select:focus,textarea:focus{outline:3px solid #c9eee6;border-color:var(--teal)}button{border:1px solid #b9d7d0;border-radius:10px;background:#ecf7f4;color:#0b6a63;font:inherit;font-size:14px;font-weight:800;padding:10px 14px;cursor:pointer}button.primary{background:var(--teal);border-color:var(--teal);color:#fff}.actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:16px}.metricgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.metric{background:#edf8f5;padding:13px;border-radius:12px}.metric small{display:block;color:#5c757e}.metric strong{display:block;font-size:clamp(19px,2.6vw,28px);line-height:1.3;overflow-wrap:anywhere}.note{font-size:13px;color:#5e7480}.warning{border-left:3px solid #e0ad56;background:#fff8e9;padding:11px 13px;font-size:13px;margin-top:18px}.item{border:1px solid #dce8e7;border-radius:11px;padding:12px;margin-top:10px;background:#fcfefe}.itemhead{display:flex;justify-content:space-between;gap:8px;align-items:center}.itemhead button{padding:5px 9px}.item p{margin:4px 0;color:#536e79;font-size:13px}.status{min-height:22px;color:#096b60;font-size:13px}.prose{margin-top:22px;background:#fff;border:1px solid var(--line);padding:20px;border-radius:15px}.prose p{color:#526b76}.preview{display:block;width:100%;border:1px solid var(--line);border-radius:10px;background:#fafafa;margin-top:12px}.tiny{font-size:12px;color:#617981}.wide{grid-column:1/-1}@media(max-width:790px){.grid{grid-template-columns:1fr}.box{padding:17px}}@media(max-width:460px){.fields,.fields.three{grid-template-columns:1fr}.app{padding:25px 12px}.metric strong{font-size:21px}}@media print{body{background:white}.app{max-width:none}.actions,.warning,.prose,.tag{display:none!important}.grid{display:block}.box{border:0;box-shadow:none}}
'''
HELPER='''
const $=id=>document.getElementById(id),num=id=>Number($(id).value),money=n=>Number(n).toLocaleString('en-US',{style:'currency',currency:'USD'}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function dl(text,name,type='text/csv'){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function csv(rows){return '\\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\\r\\n')}
function localGet(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch{return fallback}}
function localSave(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{$('status').textContent='Browser storage unavailable. Export your data now.';return false}}
'''

def page(name,title,description,body,script,explain):
    seo={'@context':'https://schema.org','@type':'SoftwareApplication','name':name,'applicationCategory':'BusinessApplication','operatingSystem':'Web','description':description,'offers':{'@type':'Offer','price':'0','priceCurrency':'USD'}}
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | {name}</title><meta name="description" content="{description}"><meta property="og:title" content="{title} | {name}"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><meta property="og:locale" content="en_US"><script type="application/ld+json">{json.dumps(seo)}</script><style>{STYLE}</style></head><body><main class="app"><div class="tag">Free browser utility · No account · Private by design</div><h1>{title}</h1><p class="intro">{description}</p>{body}<section class="prose">{explain}</section></main><script>{HELPER}\n{script}</script></body></html>'''

apps={}
# 1. Drywall takeoff: independent room dimensions, ceilings, openings, overage and sheet formats.
body='''<div class="grid"><section class="box"><h2>Room takeoff</h2><div class="fields three"><label>Room name<input id="room" value="Bedroom"></label><label>Length (ft)<input id="length" type="number" min=".1" step=".1" value="14"></label><label>Width (ft)<input id="width" type="number" min=".1" step=".1" value="12"></label><label>Wall height (ft)<input id="height" type="number" min=".1" step=".1" value="8"></label><label>Doors & windows (sq ft)<input id="openings" type="number" min="0" step="1" value="35"></label><label>Ceiling?<select id="ceiling"><option value="yes">Include ceiling</option><option value="no">Walls only</option></select></label></div><div class="actions"><button class="primary" id="add">Add room</button><button id="export">Export room CSV</button><button id="reset">Clear rooms</button></div><p id="status" class="status" role="status"></p><div id="rooms"></div></section><section class="box"><h2>Sheet estimate</h2><div class="fields"><label>Sheet size<select id="sheet"><option value="32">4 × 8 ft (32 sq ft)</option><option value="48">4 × 12 ft (48 sq ft)</option></select></label><label>Extra material allowance (%)<input id="waste" type="number" min="0" max="50" step="1" value="12"></label><label>Price per sheet ($)<input id="price" type="number" min="0" step=".01" value="18"></label></div><div class="metricgrid" style="margin-top:18px"><div class="metric"><small>Net area</small><strong id="area">0 sq ft</strong></div><div class="metric"><small>Area incl. allowance</small><strong id="gross">0 sq ft</strong></div><div class="metric"><small>Whole sheets</small><strong id="sheets">0</strong></div><div class="metric"><small>Estimated sheet cost</small><strong id="cost">$0</strong></div></div><p class="warning">Planning estimate only. Panel orientation, seams, stud spacing, code-rated assemblies, fire ratings, local rules and cut layouts can change the order. Verify onsite before purchase.</p></section></div>'''
script='''let rooms=localGet('drywallwise-v1',[]);function render(){let a=rooms.reduce((s,r)=>s+Math.max(0,2*(r.l+r.w)*r.h-r.o)+(r.c?r.l*r.w:0),0),w=Math.max(0,Math.min(50,num('waste'))),s=num('sheet'),count=Math.ceil(a*(1+w/100)/s);$('area').textContent=a.toFixed(1)+' sq ft';$('gross').textContent=(a*(1+w/100)).toFixed(1)+' sq ft';$('sheets').textContent=count;$('cost').textContent=money(count*Math.max(0,num('price')));$('rooms').innerHTML=rooms.length?rooms.map((r,i)=>`<div class="item"><div class="itemhead"><strong>${esc(r.n)}</strong><button data-remove="${i}">Remove</button></div><p>${r.l} × ${r.w} × ${r.h} ft · openings ${r.o} sq ft · ceiling ${r.c?'yes':'no'}</p></div>`).join(''):'<p class="note">Add your first room to calculate the takeoff.</p>'}function add(){let r={n:$('room').value.trim()||'Room',l:num('length'),w:num('width'),h:num('height'),o:num('openings'),c:$('ceiling').value==='yes'};if(![r.l,r.w,r.h,r.o].every(Number.isFinite)||r.l<=0||r.w<=0||r.h<=0||r.o<0||r.o>2*(r.l+r.w)*r.h){$('status').textContent='Check dimensions and openings; openings cannot exceed wall area.';return}rooms.push(r);localSave('drywallwise-v1',rooms);render();$('status').textContent='Room added locally.'}$('add').onclick=add;$('rooms').onclick=e=>{let b=e.target.closest('[data-remove]');if(b){rooms.splice(+b.dataset.remove,1);localSave('drywallwise-v1',rooms);render()}};$('reset').onclick=()=>{if(confirm('Clear room takeoff?')){rooms=[];localSave('drywallwise-v1',rooms);render()}};$('export').onclick=()=>dl(csv([['room','length_ft','width_ft','height_ft','openings_sqft','include_ceiling'],...rooms.map(r=>[r.n,r.l,r.w,r.h,r.o,r.c])]),'drywall-room-takeoff.csv');['waste','sheet','price'].forEach(id=>$(id).oninput=render);render();'''
explain='<h2>Estimate drywall sheets room by room</h2><p>Drywall takeoffs are easy to overstate when doors, windows, ceiling coverage and sheet dimensions are mixed together. Add rooms separately and subtract measured opening areas. The calculator converts net square footage to whole sheets with an explicit overage allowance.</p><p>The result is an area-based planning quantity, not a cut optimization or a construction specification. Compare the total with the actual panel layout and installer requirements.</p>'
apps['drywallwise']=page('DrywallWise','Drywall Sheet Calculator by Room','Estimate 4×8 or 4×12 drywall sheets across multiple rooms, subtract openings, add waste and export a room-by-room takeoff CSV.',body,script,explain)
# 2. Vendor map: coordinate repair vendor work per property, status and CSV
body='''<div class="grid"><section class="box"><h2>Assign a repair job</h2><div class="fields"><label>Property / unit<input id="property" maxlength="80" placeholder="Oak Street / Unit 2"></label><label>Vendor or company<input id="vendor" maxlength="80" placeholder="ABC Plumbing"></label><label>Trade<select id="trade"><option>Plumbing</option><option>Electrical</option><option>HVAC</option><option>Painting</option><option>General maintenance</option><option>Other</option></select></label><label>Job status<select id="jobstatus"><option>Requested</option><option>Scheduled</option><option>In progress</option><option>Completed</option></select></label><label>Next follow-up date<input id="date" type="date"></label><label>Job summary<input id="summary" maxlength="160" placeholder="Kitchen faucet replacement"></label></div><div class="actions"><button class="primary" id="add">Save assignment</button><button id="export">Export CSV</button><button id="clear">Clear board</button></div><p id="status" class="status" role="status"></p></section><section class="box"><h2>Vendor workload</h2><div class="metricgrid"><div class="metric"><small>Open jobs</small><strong id="open">0</strong></div><div class="metric"><small>Follow-ups overdue</small><strong id="overdue">0</strong></div><div class="metric"><small>Properties</small><strong id="properties">0</strong></div><div class="metric"><small>Vendors</small><strong id="vendors">0</strong></div></div><p class="warning">This is a browser-local coordination board. It does not contact vendors, send reminders, verify licenses or sync across devices. Avoid storing tenants' personal information.</p></section><section class="box wide"><h2>Assignments</h2><label>Filter by status<select id="filter"><option value="all">All jobs</option><option>Requested</option><option>Scheduled</option><option>In progress</option><option>Completed</option></select></label><div id="jobs"></div></section></div>'''
script='''let jobs=localGet('vendorboard-v1',[]);const today=()=>new Date().toLocaleDateString('en-CA');function render(){let open=jobs.filter(j=>j.s!=='Completed');$('open').textContent=open.length;$('overdue').textContent=open.filter(j=>j.d&&j.d<today()).length;$('properties').textContent=new Set(jobs.map(j=>j.p)).size;$('vendors').textContent=new Set(jobs.map(j=>j.v)).size;let rows=jobs.map((j,i)=>({...j,i})).filter(j=>$('filter').value==='all'||j.s===$('filter').value);$('jobs').innerHTML=rows.length?rows.map(j=>`<div class="item"><div class="itemhead"><strong>${esc(j.p)} · ${esc(j.t)}</strong><button data-remove="${j.i}">Remove</button></div><p>${esc(j.v)} · ${esc(j.x)} · follow-up ${esc(j.d||'not set')}</p><label>Status<select data-status="${j.i}">${['Requested','Scheduled','In progress','Completed'].map(s=>`<option ${s===j.s?'selected':''}>${s}</option>`).join('')}</select></label></div>`).join(''):'<p class="note">No assignments match this filter.</p>'}function add(){let j={p:$('property').value.trim(),v:$('vendor').value.trim(),t:$('trade').value,s:$('jobstatus').value,d:$('date').value,x:$('summary').value.trim()};if(!j.p||!j.v||!j.x){$('status').textContent='Enter property, vendor and job summary.';return}jobs.push(j);localSave('vendorboard-v1',jobs);render();$('status').textContent='Assignment saved on this device.'}$('add').onclick=add;$('filter').onchange=render;$('jobs').onchange=e=>{if(e.target.matches('[data-status]')){jobs[+e.target.dataset.status].s=e.target.value;localSave('vendorboard-v1',jobs);render()}};$('jobs').onclick=e=>{let b=e.target.closest('[data-remove]');if(b){jobs.splice(+b.dataset.remove,1);localSave('vendorboard-v1',jobs);render()}};$('export').onclick=()=>dl(csv([['property','vendor','trade','status','followup_date','job'],...jobs.map(j=>[j.p,j.v,j.t,j.s,j.d,j.x])]),'property-vendor-board.csv');$('clear').onclick=()=>{if(confirm('Delete all locally saved assignments?')){jobs=[];localSave('vendorboard-v1',jobs);render()}};render();'''
explain='<h2>Keep property repairs and vendors in one place</h2><p>Small landlords often coordinate multiple trades across different properties with a spreadsheet and phone contacts. VendorBoard is a focused job assignment log: enter the property, vendor, trade, next follow-up and status, then export a portable CSV.</p><p>It intentionally avoids tenant records, payment details and shared portals. Dates are for manual follow-up; this MVP does not send notifications or manage vendor credentials.</p>'
apps['vendorboard']=page('VendorBoard','Rental Property Vendor Assignment Tracker','Track which repair vendor is working at each rental property, follow-up dates and job status in a simple browser-local board.',body,script,explain)
# 3 ScopeLock: baseline and change log distinct from contractor change order price.
body='''<div class="grid"><section class="box"><h2>Project baseline</h2><div class="fields"><label>Project<input id="project" maxlength="100" placeholder="Website redesign"></label><label>Client reference<input id="client" maxlength="80" placeholder="Client A"></label><label class="wide">Agreed deliverables<textarea id="deliverables" placeholder="5 pages, responsive layout, two review rounds"></textarea></label><label class="wide">Explicit exclusions<textarea id="exclusions" placeholder="Copywriting, new integrations, extra pages"></textarea></label><label>Extra work rate ($/hour)<input id="rate" type="number" min="0" step="1" value="75"></label></div><div class="actions"><button id="save">Save baseline</button><button id="print">Print scope log</button></div><hr style="border:0;border-top:1px solid #dce9e8;margin:22px 0"><h2>Record a new request</h2><div class="fields"><label class="wide">Change requested<textarea id="change" placeholder="Add customer portal login"></textarea></label><label>Estimated extra hours<input id="hours" type="number" min="0" step=".25" value="3"></label><label>Decision<select id="decision"><option>Pending</option><option>Approved</option><option>Declined</option></select></label></div><div class="actions"><button class="primary" id="add">Add change request</button><button id="export">Export change log CSV</button></div><p id="status" class="status" role="status"></p></section><section class="box"><h2>Scope visibility</h2><div class="metricgrid"><div class="metric"><small>Requests</small><strong id="count">0</strong></div><div class="metric"><small>Pending</small><strong id="pending">0</strong></div><div class="metric"><small>Approved extra hours</small><strong id="approved">0</strong></div><div class="metric"><small>Estimated approved value</small><strong id="value">$0</strong></div></div><p class="warning">A scope log is not a contract or client approval. Status changes are self-recorded, not digitally signed. Confirm additional fees and approvals in writing.</p></section><section class="box wide"><h2>Change request log</h2><div id="changes"></div></section></div>'''
script='''let state=localGet('scopelock-v1',{base:{},changes:[]});for(let k of ['project','client','deliverables','exclusions','rate'])if(state.base[k]!=null)$(k).value=state.base[k];function persist(){state.base=Object.fromEntries(['project','client','deliverables','exclusions','rate'].map(k=>[k,$(k).value]));localSave('scopelock-v1',state)}function render(){let a=state.changes,ok=a.filter(x=>x.s==='Approved'),rate=Math.max(0,num('rate'));$('count').textContent=a.length;$('pending').textContent=a.filter(x=>x.s==='Pending').length;$('approved').textContent=ok.reduce((s,x)=>s+x.h,0).toFixed(2);$('value').textContent=money(ok.reduce((s,x)=>s+x.h,0)*rate);$('changes').innerHTML=a.length?a.map((x,i)=>`<div class="item"><div class="itemhead"><strong>Request ${i+1}</strong><button data-remove="${i}">Remove</button></div><p>${esc(x.text)}</p><p>${x.h} hours · ${esc(x.date)}</p><label>Decision<select data-decision="${i}">${['Pending','Approved','Declined'].map(s=>`<option ${x.s===s?'selected':''}>${s}</option>`).join('')}</select></label></div>`).join(''):'<p class="note">No change requests logged yet.</p>'}$('save').onclick=()=>{persist();$('status').textContent='Baseline saved locally.'};$('add').onclick=()=>{let text=$('change').value.trim(),h=num('hours');if(!text||!Number.isFinite(h)||h<0||h>10000){$('status').textContent='Enter a change description and valid hours.';return}state.changes.push({text,h,s:$('decision').value,date:new Date().toISOString().slice(0,10)});persist();$('change').value='';render();$('status').textContent='Change request recorded.'};$('changes').onchange=e=>{if(e.target.matches('[data-decision]')){state.changes[+e.target.dataset.decision].s=e.target.value;persist();render()}};$('changes').onclick=e=>{let b=e.target.closest('[data-remove]');if(b){state.changes.splice(+b.dataset.remove,1);persist();render()}};$('export').onclick=()=>{persist();dl(csv([['project','client','deliverables','exclusions','request','hours','decision','date','hourly_rate'],...state.changes.map(x=>[$('project').value,$('client').value,$('deliverables').value,$('exclusions').value,x.text,x.h,x.s,x.date,num('rate')])]),'freelance-scope-log.csv')};$('print').onclick=()=>{persist();window.print()};$('rate').oninput=render;render();'''
explain='<h2>Make client scope changes visible before they become free work</h2><p>Freelance work often expands when deliverables were not specific enough or clients ask for additional revisions. ScopeLock records the agreed baseline, exclusions and each new request separately from the original scope.</p><p>Estimate the extra hours, record whether the request is pending, approved or declined, and export a decision log for discussion. It does not email clients or prove their consent; retain the signed agreement and client correspondence separately.</p>'
apps['scopelock']=page('ScopeLock','Freelance Scope Creep and Change Request Tracker','Record agreed deliverables, exclusions and extra client requests; track decisions, estimated extra hours and export a change log.',body,script,explain)
# 4 Contact sheet generator
body='''<div class="grid"><section class="box"><h2>Build a contact sheet</h2><div class="fields"><label class="wide">Choose JPEG, PNG or WebP images<input id="files" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label>Columns<select id="cols"><option value="2">2 columns</option><option value="3" selected>3 columns</option><option value="4">4 columns</option><option value="5">5 columns</option></select></label><label>Thumbnail width (px)<input id="tile" type="number" min="90" max="450" step="10" value="220"></label><label>Captions<select id="caption"><option value="filename">File names</option><option value="number">Image numbers</option><option value="none">No captions</option></select></label><label>Title<input id="heading" maxlength="80" value="Photo proof contact sheet"></label></div><div class="actions"><button class="primary" id="generate">Generate preview</button><button id="download">Download PNG</button><button id="clear">Clear images</button></div><p id="status" class="status" role="status"></p><p class="note">Photos stay in this browser. Large batches can consume substantial memory. JPEG EXIF orientation support depends on the browser.</p></section><section class="box"><h2>Preview</h2><div class="metricgrid"><div class="metric"><small>Selected photos</small><strong id="count">0</strong></div><div class="metric"><small>Output size</small><strong id="size">—</strong></div></div><canvas id="canvas" class="preview" width="660" height="300" aria-label="Contact sheet preview"></canvas><p class="warning">This exports a raster PNG proof sheet, not a shared online gallery, client approval portal or original-resolution image archive.</p></section></div>'''
script='''let pics=[];const can=$('canvas'),ctx=can.getContext('2d');async function load(){pics.forEach(p=>URL.revokeObjectURL(p.url));pics=[];let files=[...$('files').files].slice(0,36);for(let f of files){if(!['image/jpeg','image/png','image/webp'].includes(f.type))continue;let url=URL.createObjectURL(f),im=new Image();try{await new Promise((ok,bad)=>{im.onload=ok;im.onerror=bad;im.src=url});pics.push({name:f.name,im,url})}catch{URL.revokeObjectURL(url)}}$('count').textContent=pics.length;$('status').textContent=files.length>36?'Limited to 36 photos per sheet.':'Images ready. Generate the preview.';if(pics.length)draw()}function draw(){let cols=+num('cols'),tile=Math.min(450,Math.max(90,num('tile'))),gap=14,pad=20,caption=$('caption').value,title=$('heading').value.trim(),cellH=tile*.75+(caption==='none'?0:32),rows=Math.max(1,Math.ceil(pics.length/cols));can.width=pad*2+cols*tile+(cols-1)*gap;can.height=pad*2+44+rows*cellH+(rows-1)*gap;ctx.fillStyle='#fff';ctx.fillRect(0,0,can.width,can.height);ctx.fillStyle='#1b3542';ctx.font='bold 20px sans-serif';ctx.fillText(title.slice(0,60)||'Contact sheet',pad,pad+22);pics.forEach((p,i)=>{let col=i%cols,row=Math.floor(i/cols),x=pad+col*(tile+gap),y=pad+44+row*(cellH+gap),im=p.im,iw=im.naturalWidth,ih=im.naturalHeight,scale=Math.min(tile/iw,(tile*.75)/ih),w=iw*scale,h=ih*scale;ctx.fillStyle='#f1f5f5';ctx.fillRect(x,y,tile,tile*.75);ctx.drawImage(im,x+(tile-w)/2,y+(tile*.75-h)/2,w,h);if(caption!=='none'){ctx.fillStyle='#24424d';ctx.font='12px sans-serif';let txt=caption==='number'?'#'+(i+1):p.name;ctx.fillText(txt.slice(0,Math.max(9,Math.floor(tile/8))),x,y+tile*.75+20)}});$('size').textContent=can.width+' × '+can.height+' px';$('status').textContent='Contact sheet generated locally.'}$('files').onchange=load;$('generate').onclick=()=>{if(!pics.length){$('status').textContent='Choose at least one supported image.';return}draw()};$('download').onclick=()=>{if(!pics.length){$('status').textContent='Choose images first.';return}draw();can.toBlob(b=>{if(!b){$('status').textContent='PNG export failed.';return}let u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='photo-contact-sheet.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)},'image/png')};$('clear').onclick=()=>{pics.forEach(p=>URL.revokeObjectURL(p.url));pics=[];$('files').value='';$('count').textContent=0;$('size').textContent='—';ctx.clearRect(0,0,can.width,can.height);$('status').textContent='Photos cleared.'};['cols','tile','caption','heading'].forEach(id=>$(id).onchange=()=>{if(pics.length)draw()});'''
explain='<h2>Create a numbered proof sheet without a cloud upload</h2><p>Photographers often need a quick overview of image selections without creating a full client gallery. Upload up to 36 JPEG, PNG or WebP images, choose the column count and caption style, and download a single contact-sheet PNG.</p><p>The photos are decoded locally and never sent to a Worklane server by this tool. Output is a raster proof image for review, not a color-managed print production file. Export before closing the tab.</p>'
apps['proofsheet']=page('ProofSheet','Free Photo Contact Sheet Generator','Create a numbered photo contact sheet from local images, customize the layout and download a single PNG without uploading photos.',body,script,explain)
# 5 Lease calendar - date only and all day ICS events, user-entered notice windows
body='''<div class="grid"><section class="box"><h2>Add a lease timeline</h2><div class="fields"><label>Property reference<input id="property" maxlength="90" placeholder="Unit 4 / Maple Street"></label><label>Lease end date<input id="end" type="date"></label><label>Notice lead time (days)<input id="notice" type="number" min="0" max="365" step="1" value="60"></label><label>Planning reminder lead (days)<input id="reminder" type="number" min="0" max="365" step="1" value="90"></label></div><div class="actions"><button class="primary" id="add">Add lease</button><button id="ics">Download calendar (.ics)</button><button id="export">Export CSV</button></div><p id="status" class="status" role="status"></p><div id="leases"></div></section><section class="box"><h2>Upcoming deadlines</h2><div class="metricgrid"><div class="metric"><small>Tracked leases</small><strong id="count">0</strong></div><div class="metric"><small>Notice dates passed</small><strong id="late">0</strong></div></div><p class="warning">You must enter the correct lease and legally applicable notice period. This tool does not determine state/local law, deliver notices, verify delivery, or send automatic reminders. Import the .ics file into your own calendar and check the events.</p></section></div>'''
script='''let leases=localGet('leasetick-v1',[]);function addDays(date,n){let d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}function today(){let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}function render(){$('count').textContent=leases.length;$('late').textContent=leases.filter(x=>addDays(x.e,-x.n)<today()).length;$('leases').innerHTML=leases.length?leases.map((x,i)=>`<div class="item"><div class="itemhead"><strong>${esc(x.p)}</strong><button data-remove="${i}">Remove</button></div><p>Lease ends: ${x.e}</p><p>Notice date (entered ${x.n} days): <strong>${addDays(x.e,-x.n)}</strong></p><p>Planning reminder: ${addDays(x.e,-x.r)}</p></div>`).join(''):'<p class="note">Add your first lease to create a calendar export.</p>'}$('add').onclick=()=>{let p=$('property').value.trim(),e=$('end').value,n=num('notice'),r=num('reminder');if(!p||!/^\\d{4}-\\d{2}-\\d{2}$/.test(e)||![n,r].every(x=>Number.isInteger(x)&&x>=0&&x<=365)){$('status').textContent='Enter property, lease end and valid lead times.';return}leases.push({p,e,n,r});localSave('leasetick-v1',leases);render();$('status').textContent='Lease timeline saved locally.'};$('leases').onclick=e=>{let b=e.target.closest('[data-remove]');if(b){leases.splice(+b.dataset.remove,1);localSave('leasetick-v1',leases);render()}};$('export').onclick=()=>dl(csv([['property','lease_end','notice_lead_days','notice_date','reminder_lead_days','reminder_date'],...leases.map(x=>[x.p,x.e,x.n,addDays(x.e,-x.n),x.r,addDays(x.e,-x.r)])]),'lease-renewal-timeline.csv');function icsEsc(s){return String(s).replaceAll('\\\\','\\\\\\\\').replaceAll(';','\\\\;').replaceAll(',','\\\\,').replaceAll('\\n','\\\\n')}function ev(name,date,i){let day=date.replaceAll('-',''),next=addDays(date,1).replaceAll('-','');return ['BEGIN:VEVENT','UID:worklane-'+i+'-'+day+'@local','DTSTAMP:20261021T000000Z','DTSTART;VALUE=DATE:'+day,'DTEND;VALUE=DATE:'+next,'SUMMARY:'+icsEsc(name),'DESCRIPTION:Verify the lease and applicable notice rules. This event does not send notice.','END:VEVENT'].join('\\r\\n')}$('ics').onclick=()=>{if(!leases.length){$('status').textContent='Add a lease first.';return}let events=leases.flatMap((x,i)=>[ev('Planning: '+x.p,addDays(x.e,-x.r),i+'a'),ev('Review notice deadline: '+x.p,addDays(x.e,-x.n),i+'b'),ev('Lease ends: '+x.p,x.e,i+'c')]);dl('BEGIN:VCALENDAR\\r\\nVERSION:2.0\\r\\nPRODID:-//Worklane Tools//LeaseTick//EN\\r\\nCALSCALE:GREGORIAN\\r\\n'+events.join('\\r\\n')+'\\r\\nEND:VCALENDAR\\r\\n','lease-renewal-calendar.ics','text/calendar;charset=utf-8');$('status').textContent='Calendar file downloaded. Import it into your calendar app.'};render();'''
explain='<h2>Turn lease dates into your own calendar events</h2><p>Independent landlords may track lease expirations in spreadsheets and calendar notes. LeaseTick converts each entered lease end date and your chosen lead times into planning and notice-review dates, then exports a standard iCalendar file.</p><p>Lead times are user supplied because notice requirements vary by jurisdiction, lease and situation. Always verify legal requirements and actual notice delivery separately. Downloaded events are not automatic alerts until imported into a calendar that supports reminders.</p>'
apps['leasetick']=page('LeaseTick','Lease Renewal Date and Notice Calendar Planner','Track lease expiration dates, calculate user-defined notice and planning dates, and export reminders to an iCalendar .ics file.',body,script,explain)

for slug,html in apps.items():
    p=R/'apps'/slug/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html,encoding='utf-8')
print('Wrote',len(apps),'H5 apps')
